CREATE TABLE seniorities(id INTEGER PRIMARY KEY, name TEXT UNIQUE NOT NULL, target_factor REAL NOT NULL DEFAULT 1 CHECK(target_factor>0));
INSERT INTO seniorities(name,target_factor) VALUES('Junior',0.7),('Mid-Level',1),('Senior',1.25),('Team Leader',1.4),('Manager',1.5);
ALTER TABLE employees ADD COLUMN seniority_id INTEGER REFERENCES seniorities(id);
ALTER TABLE employees ADD COLUMN certifications TEXT NOT NULL DEFAULT '';
ALTER TABLE teams ADD COLUMN leader_id INTEGER REFERENCES employees(id);
ALTER TABLE teams ADD COLUMN manager_id INTEGER REFERENCES employees(id);
CREATE TABLE team_access(user_id INTEGER REFERENCES users(id), team_id INTEGER REFERENCES teams(id), PRIMARY KEY(user_id,team_id));
INSERT INTO roles(id,label) VALUES('sales','Sales Employee'),('sales_leader','Sales Team Leader'),('sales_manager','Sales Contracts Manager'),('accountant','Accounting'),('project_manager','Project Manager'),('executive','Executive Management'),('admin','Administrator');
CREATE TABLE accounts(id INTEGER PRIMARY KEY, name TEXT NOT NULL, industry TEXT NOT NULL DEFAULT '', email TEXT DEFAULT '', phone TEXT DEFAULT '', website TEXT DEFAULT '', business_info TEXT DEFAULT '', owner_id INTEGER NOT NULL REFERENCES employees(id), team_id INTEGER REFERENCES teams(id), status TEXT NOT NULL DEFAULT 'Prospect', notes TEXT DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_accounts_name ON accounts(name COLLATE NOCASE);
CREATE TABLE contacts(id INTEGER PRIMARY KEY, account_id INTEGER NOT NULL REFERENCES accounts(id), name TEXT NOT NULL, job_title TEXT DEFAULT '', email TEXT DEFAULT '', phone TEXT DEFAULT '', preference TEXT DEFAULT 'Email', contact_role TEXT DEFAULT '', notes TEXT DEFAULT '', owner_id INTEGER NOT NULL REFERENCES employees(id), created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE lead_sources(id INTEGER PRIMARY KEY, name TEXT UNIQUE NOT NULL);
INSERT INTO lead_sources(name) VALUES('Referral'),('Website'),('Outbound'),('Event'),('Social media');
CREATE TABLE pipeline_stages(id INTEGER PRIMARY KEY, name TEXT UNIQUE NOT NULL, position INTEGER NOT NULL, probability REAL NOT NULL CHECK(probability BETWEEN 0 AND 100), outcome TEXT NOT NULL DEFAULT 'Open' CHECK(outcome IN ('Open','Won','Lost')));
INSERT INTO pipeline_stages(name,position,probability,outcome) VALUES('Qualification',1,15,'Open'),('Discovery',2,30,'Open'),('Proposal',3,50,'Open'),('Negotiation',4,75,'Open'),('Won',5,100,'Won'),('Lost',6,0,'Lost');
CREATE TABLE services(id INTEGER PRIMARY KEY, name TEXT UNIQUE NOT NULL, description TEXT DEFAULT '', price_cents INTEGER NOT NULL DEFAULT 0 CHECK(price_cents>=0), status TEXT DEFAULT 'Active');
INSERT INTO services(name,description) VALUES('Social Media Management','Content calendar, publishing and community care'),('Paid Advertising','Campaign strategy and optimization; advertising spend accounted separately'),('Photography Production','Pre-production, shoot and photo delivery'),('Video Production','Scripts, production, editing and delivery'),('Content Creation','Copywriting, captions and editorial planning'),('Branding & Graphic Design','Brand strategy, design and assets'),('Full Digital Marketing','Integrated account delivery');
CREATE TABLE leads(id INTEGER PRIMARY KEY, name TEXT NOT NULL, company_name TEXT NOT NULL, contact_name TEXT DEFAULT '', email TEXT DEFAULT '', phone TEXT DEFAULT '', industry TEXT DEFAULT '', source_id INTEGER REFERENCES lead_sources(id), owner_id INTEGER NOT NULL REFERENCES employees(id), team_id INTEGER NOT NULL REFERENCES teams(id), expected_cents INTEGER NOT NULL DEFAULT 0 CHECK(expected_cents>=0), interested_services TEXT NOT NULL DEFAULT '[]', status TEXT NOT NULL DEFAULT 'New', priority TEXT DEFAULT 'Medium', qualification TEXT DEFAULT 'Unqualified', score REAL NOT NULL DEFAULT 0 CHECK(score BETWEEN 0 AND 100), next_followup TEXT, notes TEXT DEFAULT '', converted_deal_id INTEGER, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE deals(id INTEGER PRIMARY KEY, name TEXT NOT NULL, account_id INTEGER NOT NULL REFERENCES accounts(id), contact_id INTEGER REFERENCES contacts(id), owner_id INTEGER NOT NULL REFERENCES employees(id), team_id INTEGER NOT NULL REFERENCES teams(id), value_cents INTEGER NOT NULL DEFAULT 0 CHECK(value_cents>=0), currency TEXT NOT NULL DEFAULT 'EGP', stage_id INTEGER NOT NULL REFERENCES pipeline_stages(id), probability REAL NOT NULL CHECK(probability BETWEEN 0 AND 100), expected_close TEXT NOT NULL, actual_close TEXT, services TEXT NOT NULL DEFAULT '[]', competitors TEXT DEFAULT '', notes TEXT DEFAULT '', lost_reason TEXT DEFAULT '', converted_contract_id INTEGER, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE activities(id INTEGER PRIMARY KEY, title TEXT NOT NULL, kind TEXT NOT NULL, lead_id INTEGER REFERENCES leads(id), contact_id INTEGER REFERENCES contacts(id), account_id INTEGER REFERENCES accounts(id), deal_id INTEGER REFERENCES deals(id), owner_id INTEGER NOT NULL REFERENCES employees(id), due TEXT NOT NULL, status TEXT DEFAULT 'Planned', outcome TEXT DEFAULT '', notes TEXT DEFAULT '', created_at TEXT DEFAULT CURRENT_TIMESTAMP, CHECK(lead_id IS NOT NULL OR contact_id IS NOT NULL OR account_id IS NOT NULL OR deal_id IS NOT NULL));
CREATE TABLE quotations(id INTEGER PRIMARY KEY, title TEXT NOT NULL, deal_id INTEGER NOT NULL REFERENCES deals(id), version INTEGER NOT NULL DEFAULT 1, parent_id INTEGER REFERENCES quotations(id), kind TEXT DEFAULT 'Quotation', expires TEXT NOT NULL, discount_percent REAL NOT NULL DEFAULT 0 CHECK(discount_percent BETWEEN 0 AND 100), status TEXT NOT NULL DEFAULT 'Draft', client_status TEXT DEFAULT 'Not sent', notes TEXT DEFAULT '', total_cents INTEGER NOT NULL DEFAULT 0, owner_id INTEGER NOT NULL REFERENCES employees(id), created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE quotation_lines(id INTEGER PRIMARY KEY, quotation_id INTEGER NOT NULL REFERENCES quotations(id), service_id INTEGER REFERENCES services(id), description TEXT NOT NULL, quantity REAL NOT NULL CHECK(quantity>0), price_cents INTEGER NOT NULL CHECK(price_cents>=0));
CREATE TABLE client_contracts(id INTEGER PRIMARY KEY, name TEXT NOT NULL, account_id INTEGER NOT NULL REFERENCES accounts(id), deal_id INTEGER REFERENCES deals(id), quotation_id INTEGER REFERENCES quotations(id), owner_id INTEGER NOT NULL REFERENCES employees(id), value_cents INTEGER NOT NULL CHECK(value_cents>=0), currency TEXT DEFAULT 'EGP', start TEXT NOT NULL, end TEXT NOT NULL, renewal TEXT, payment_terms TEXT NOT NULL, services TEXT DEFAULT '[]', status TEXT NOT NULL DEFAULT 'Draft', notes TEXT DEFAULT '', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sales_targets(id INTEGER PRIMARY KEY, title TEXT NOT NULL, employee_id INTEGER REFERENCES employees(id), team_id INTEGER REFERENCES teams(id), month TEXT NOT NULL, target_cents INTEGER NOT NULL CHECK(target_cents>0), CHECK(employee_id IS NOT NULL OR team_id IS NOT NULL));
CREATE TABLE project_templates(id INTEGER PRIMARY KEY, name TEXT UNIQUE NOT NULL, workflow TEXT NOT NULL, description TEXT DEFAULT '');
CREATE TABLE projects(id INTEGER PRIMARY KEY, name TEXT NOT NULL, account_id INTEGER NOT NULL REFERENCES accounts(id), contract_id INTEGER NOT NULL REFERENCES client_contracts(id), manager_id INTEGER NOT NULL REFERENCES employees(id), template_id INTEGER REFERENCES project_templates(id), start TEXT NOT NULL, deadline TEXT NOT NULL, budget_cents INTEGER NOT NULL DEFAULT 0 CHECK(budget_cents>=0), estimated_hours REAL NOT NULL DEFAULT 0 CHECK(estimated_hours>=0), status TEXT DEFAULT 'Planning', priority TEXT DEFAULT 'Medium', notes TEXT DEFAULT '', results TEXT DEFAULT '', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE project_members(id INTEGER PRIMARY KEY, project_id INTEGER NOT NULL REFERENCES projects(id), employee_id INTEGER NOT NULL REFERENCES employees(id), responsibility TEXT DEFAULT '', UNIQUE(project_id,employee_id));
CREATE TABLE project_departments(project_id INTEGER REFERENCES projects(id), department_id INTEGER REFERENCES departments(id), PRIMARY KEY(project_id,department_id));
CREATE TABLE milestones(id INTEGER PRIMARY KEY, project_id INTEGER NOT NULL REFERENCES projects(id), title TEXT NOT NULL, due TEXT NOT NULL, status TEXT DEFAULT 'Planned');
CREATE TABLE project_risks(id INTEGER PRIMARY KEY, project_id INTEGER NOT NULL REFERENCES projects(id), title TEXT NOT NULL, severity TEXT DEFAULT 'Medium', mitigation TEXT NOT NULL, owner_id INTEGER NOT NULL REFERENCES employees(id), status TEXT DEFAULT 'Open');
CREATE TABLE campaigns(id INTEGER PRIMARY KEY, project_id INTEGER NOT NULL REFERENCES projects(id), name TEXT NOT NULL, channel TEXT NOT NULL, objective TEXT NOT NULL, start TEXT NOT NULL, end TEXT NOT NULL, advertising_budget_cents INTEGER NOT NULL DEFAULT 0 CHECK(advertising_budget_cents>=0), advertising_spend_cents INTEGER NOT NULL DEFAULT 0 CHECK(advertising_spend_cents>=0), impressions INTEGER DEFAULT 0 CHECK(impressions>=0), clicks INTEGER DEFAULT 0 CHECK(clicks>=0), conversions INTEGER DEFAULT 0 CHECK(conversions>=0), attributed_revenue_cents INTEGER DEFAULT 0 CHECK(attributed_revenue_cents>=0), status TEXT DEFAULT 'Planning');
ALTER TABLE tasks ADD COLUMN project_id INTEGER REFERENCES projects(id);
ALTER TABLE tasks ADD COLUMN assigned_by INTEGER REFERENCES employees(id);
ALTER TABLE tasks ADD COLUMN department_id INTEGER REFERENCES departments(id);
ALTER TABLE tasks ADD COLUMN quality_score REAL CHECK(quality_score BETWEEN 0 AND 100);
ALTER TABLE tasks ADD COLUMN delay_context TEXT DEFAULT '';
CREATE TABLE task_dependencies(task_id INTEGER REFERENCES tasks(id), depends_on_id INTEGER REFERENCES tasks(id), PRIMARY KEY(task_id,depends_on_id), CHECK(task_id!=depends_on_id));
CREATE TABLE deliverables(id INTEGER PRIMARY KEY, project_id INTEGER NOT NULL REFERENCES projects(id), task_id INTEGER REFERENCES tasks(id), employee_id INTEGER NOT NULL REFERENCES employees(id), title TEXT NOT NULL, kind TEXT NOT NULL, brief TEXT NOT NULL, asset_url TEXT DEFAULT '', publish_at TEXT, status TEXT DEFAULT 'Draft', version INTEGER NOT NULL DEFAULT 1, quality_score REAL CHECK(quality_score BETWEEN 0 AND 100), revisions INTEGER NOT NULL DEFAULT 0, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE deliverable_reviews(id INTEGER PRIMARY KEY, deliverable_id INTEGER NOT NULL REFERENCES deliverables(id), reviewer_id INTEGER NOT NULL REFERENCES employees(id), decision TEXT NOT NULL, comment TEXT NOT NULL, quality_score REAL CHECK(quality_score BETWEEN 0 AND 100), created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE task_comments(id INTEGER PRIMARY KEY, task_id INTEGER NOT NULL REFERENCES tasks(id), author_id INTEGER NOT NULL REFERENCES employees(id), comment TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE time_records(id INTEGER PRIMARY KEY, task_id INTEGER NOT NULL REFERENCES tasks(id), employee_id INTEGER NOT NULL REFERENCES employees(id), day TEXT NOT NULL, hours REAL NOT NULL CHECK(hours>0 AND hours<=24), notes TEXT DEFAULT '', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE project_costs(id INTEGER PRIMARY KEY, project_id INTEGER NOT NULL REFERENCES projects(id), title TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('Internal','External production','Advertising spend')), amount_cents INTEGER NOT NULL CHECK(amount_cents>=0), day TEXT NOT NULL, reason TEXT NOT NULL);
CREATE TABLE payments(id INTEGER PRIMARY KEY, contract_id INTEGER NOT NULL REFERENCES client_contracts(id), amount_cents INTEGER NOT NULL CHECK(amount_cents>0), day TEXT NOT NULL, reference TEXT NOT NULL, notes TEXT DEFAULT '');
CREATE TABLE crm_custom_fields(id INTEGER PRIMARY KEY, entity TEXT NOT NULL, name TEXT NOT NULL, kind TEXT DEFAULT 'text', UNIQUE(entity,name));
CREATE TABLE custom_values(field_id INTEGER REFERENCES crm_custom_fields(id), record_id INTEGER NOT NULL, value TEXT NOT NULL, PRIMARY KEY(field_id,record_id));
CREATE TABLE saved_views(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), entity TEXT NOT NULL, name TEXT NOT NULL, filters TEXT NOT NULL DEFAULT '{}', columns TEXT NOT NULL DEFAULT '[]');
CREATE TABLE audit_logs(id INTEGER PRIMARY KEY, actor_id INTEGER REFERENCES users(id), entity TEXT NOT NULL, record_id INTEGER, action TEXT NOT NULL, before_data TEXT, after_data TEXT, reason TEXT DEFAULT '', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_audit_entity ON audit_logs(entity,record_id);
CREATE TABLE business_attachments(id INTEGER PRIMARY KEY, entity TEXT NOT NULL, record_id INTEGER NOT NULL, name TEXT NOT NULL, storage_key TEXT NOT NULL, mime TEXT NOT NULL, uploaded_by INTEGER NOT NULL REFERENCES users(id), created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE forecast_snapshots(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), month TEXT NOT NULL, predicted_cents INTEGER NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
INSERT INTO schema_versions(version) VALUES(5);
